JohtoStableIDToActiveSlotEnd::
ASSERT JohtoStableIDToActiveSlotEnd - JohtoStableIDToActiveSlot == JOHTO_STABLE_ID_TABLE_SIZE
; Nine active maps: Route32 adds the sixth outdoor; the house and gate remain intact.
; Keep this equality consistent with region_map_constants.asm and all 9 descriptor rows.
ASSERT NUM_JOHTO_ACTIVE_MAPS == 9

; Input E=stable Johto ID. Output E=compact active slot or $ff.
; Preserves BC, HL and D. A/flags are volatile. When called using callab,
; use E for the result, NOT A/carry (Bankswitch can overwrite them).
; The 16-bit index handles the full 0..255 input range without wrapping.
GetJohtoActiveSlot::
	push bc
	push hl
	ld l, e
	ld h, 0
	ld bc, JohtoStableIDToActiveSlot
	add hl, bc
	ld a, [hl]
	; An unregistered or malformed slot must not reach any data array.
	cp NUM_JOHTO_ACTIVE_MAPS
	jr c, .valid
	ld a, JOHTO_INVALID_ACTIVE_SLOT
.valid
	ld e, a
	pop hl
	pop bc
	ret
